WITH lines AS (SELECT id, effective_from, currency, element FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) t AS element) SELECT CASE WHEN element >= 62 THEN 'HIGH' ELSE 'LOW' END AS element_tier, COUNT_IF(currency = 'USD') AS usd_events, PERCENTILE_APPROX(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles, COUNT(CASE WHEN currency = 'USD' THEN 1 END) AS usd_count, AVG(element) FILTER (WHERE currency = 'EUR') AS eur_avg_element, SORT_ARRAY(COLLECT_SET(currency)) AS currency_list FROM lines GROUP BY CASE WHEN element >= 62 THEN 'HIGH' ELSE 'LOW' END;
